{% set price = states('sensor.nordpool') %}
{% set known = is_number(price) %}
{% set p = price | float(0) %}
{% set entries = state_attr('sensor.nordpool', 'raw_today') or [] %}
{% set values = entries | map(attribute='value') | select('number') | list %}
{% set lo = values | min if values else p %}
{% set hi = values | max if values else p %}
{% set ratio = ([0, ([1, ((p-lo)/(hi-lo))] | min)] | max) if known and hi > lo else 0 %}
{% set rgb = '100, 181, 198' if p < 2 else '245, 207, 92' if p < 3 else '239, 156, 74' if p < 4 else '226, 96, 83' %}
ha-card {
 position: relative;
 isolation: isolate;
 overflow: hidden;
 background: linear-gradient(160deg, #285577 0%, #203e56 45%, #192f40 100%) !important;
 --primary-text-color: #eef4f8;
 --secondary-text-color: #c2ced7;
}
ha-card::before {
 content: '';
 position: absolute;
 inset: 0;
 z-index: -1;
 pointer-events: none;
 border-radius: inherit;
 background-image: radial-gradient(ellipse at 35% 25%, rgba({{ rgb }}, {{ (0.12 + ratio * 0.16) | round(3) }}) 0%, transparent 65%);
 background-size: 160% 180%;
 background-position: 0% 30%;
 opacity: {{ 1 if known else 0 }};
 animation: {{ 'price-light-drift 20s ease-in-out infinite alternate' if known else 'none' }};
}
@keyframes price-light-drift {
 from { background-position: 0% 30%; }
 to { background-position: 100% 70%; }
}
@media (prefers-reduced-motion: reduce) {
 ha-card::before { animation: none; }
}
